insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(1401, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'La mise en place de la ouate ou du coton cardé avant une attelle ou un plâtre circulaire est faite pour :', '[{"l":"A","t":"Protéger la peau","c":true},{"l":"B","t":"Protéger les axes vasculo-nerveux","c":true},{"l":"C","t":"Protéger les saillies osseuses","c":true},{"l":"D","t":"Eviter toute incongruence entre l''attelle et le membre","c":true},{"l":"E","t":"Toutes les réponses sont justes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1402, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Le décollement type 3 de SALTER et HARRIS : (cochez la ou les réponses justes)', '[{"l":"A","t":"Est de mauvais pronostic si la réduction n’est pas anatomique","c":true},{"l":"B","t":"Est un décollement épiphysaire avec détachement d’un coin épiphyso-Métaphysaire","c":true},{"l":"C","t":"Est un décollement épiphysaire pur","c":false},{"l":"D","t":"La plaque conjugale (cartilage de croissance) est rompue","c":true},{"l":"E","t":"Il y a un risque d’épiphysiodèse en cas de mauvaise réduction.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1403, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le plâtre circulaire :', '[{"l":"A","t":"Est un geste médical","c":false},{"l":"B","t":"Doit se faire en présence a une se faire en présence d’une tierce personne parent de l’accompagnateur)","c":false},{"l":"C","t":"Les recommandations doivent être faites en présence d’une tierce personne","c":true},{"l":"D","t":"Doit être fendu immédiatement","c":true},{"l":"E","t":"Impose une surveillance de 24h en milieu hospitalier","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1404, 1, 'Autre', 'Non classé', NULL, false, true, 'La fracture en motte de beurre est :', '[{"l":"A","t":"une fracture de bon pronostic","c":true},{"l":"B","t":"dûe à l’enfoncement de la diaphyse dans la métaphyse","c":true},{"l":"C","t":"il n’y a pas de rupture de la corticale","c":true},{"l":"D","t":"il y a un risque d’épiphysiodèse","c":false},{"l":"E","t":"toutes les réponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1405, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'La classification de Salter et Harris :', '[{"l":"A","t":"Type I est un décollement épiphysaire","c":true},{"l":"B","t":"Type II est un décollement avec le détachement d’un fragment métaphysaire","c":true},{"l":"C","t":"Type III est une fracture épiphyso-métaphysaire","c":false},{"l":"D","t":"Type IV est un décollement avec détachement d’un fragment épiphysaire","c":false},{"l":"E","t":"Type V est la fracture tassement","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1406, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', NULL, false, true, 'Un jeune homme de 20 ans présente une fracture plurifragmentaire des deux os de la jambe, ouverte, de type 3, sans lésion vasculo-nerveuse. Quel traitement local est justifié ?', '[{"l":"A","t":"ostéosynthèse par plaque vissée","c":false},{"l":"B","t":"parage et fixateur externe","c":false},{"l":"C","t":"plâtre fermé cruropédieux","c":false},{"l":"D","t":"enclouage verrouillé","c":true},{"l":"E","t":"traction continue","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1407, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'La consolidation d’une fracture du tibia est :', '[{"l":"A","t":"Très rapide","c":false},{"l":"B","t":"Rapide","c":false},{"l":"C","t":"Longue","c":true},{"l":"D","t":"Impossible","c":false},{"l":"E","t":"Sans risque de complication","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1408, 1, 'Chirurgie pédiatrique', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Le “décollement épiphysaire” est une fracture qui touche :', '[{"l":"A","t":"Le cartilage de croissance","c":true},{"l":"B","t":"La diaphyse","c":false},{"l":"C","t":"La métaphyse","c":false},{"l":"D","t":"L’épiphyse","c":false},{"l":"E","t":"La métaphyse et la diaphyse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1409, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Le traitement d’une fracture de la patella non déplacée est :', '[{"l":"A","t":"La chirurgie","c":false},{"l":"B","t":"L’immobilisation plâtrée","c":true},{"l":"C","t":"Le repos au lit","c":false},{"l":"D","t":"La traction","c":false},{"l":"E","t":"Le traitement fonctionnel","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1410, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Le traitement d’une fracture de la patella déplacée est :', '[{"l":"A","t":"L’immobilisation","c":false},{"l":"B","t":"Le repos au lit","c":false},{"l":"C","t":"La chirurgie","c":true},{"l":"D","t":"La traction","c":false},{"l":"E","t":"Un traitement fonctionnel","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1411, 8, 'Autre', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le diagnostic est fait par :', '[{"l":"A","t":"La radiographie","c":false},{"l":"B","t":"L’échographie","c":false},{"l":"C","t":"Le scanner","c":true},{"l":"D","t":"L’IRM","c":false},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1412, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'Le traitement d’une fracture de la palette humérale est le plus souvent :', '[{"l":"A","t":"Chirurgical","c":true},{"l":"B","t":"Fonctionnel","c":false},{"l":"C","t":"Une immobilisation simple","c":false},{"l":"D","t":"Une traction","c":false},{"l":"E","t":"Un plâtre","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1413, 43, 'Traumatologie', 'Syndrome des loges', NULL, false, true, 'La principale cause de mortalité dans les fractures du bassin est :', '[{"l":"A","t":"Le syndrome des loges","c":false},{"l":"B","t":"L’hémorragie","c":true},{"l":"C","t":"L’atteinte nerveuse","c":false},{"l":"D","t":"L’atteinte viscérale","c":false},{"l":"E","t":"Le choc septique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1414, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Le traitement chirurgical d’une fracture de la tête radiale est indiqué en cas de :', '[{"l":"A","t":"Fracture de type I","c":false},{"l":"B","t":"Fracture peu déplacée","c":false},{"l":"C","t":"Fracture associée à une luxation du coude","c":true},{"l":"D","t":"Fracture chez un enfant","c":false},{"l":"E","t":"Douleur minime","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1415, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'La chirurgie d’une fracture de la patella déplacée est une :', '[{"l":"A","t":"Ostéosynthèse","c":true},{"l":"B","t":"Arthrodèse","c":false},{"l":"C","t":"Méniscectomie","c":false},{"l":"D","t":"Prothèse","c":false},{"l":"E","t":"Réduction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1416, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Une fracture est dite stable lorsque :', '[{"l":"A","t":"Elle n’est pas ouverte","c":false},{"l":"B","t":"Le traitement est chirurgical","c":false},{"l":"C","t":"L’immobilisation seule suffit pour assurer la consolidation","c":true},{"l":"D","t":"Elle touche une articulation","c":false},{"l":"E","t":"Elle est associée à une luxation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1417, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Les fractures du bassin instables nécessitent un traitement :', '[{"l":"A","t":"Fonctionnel","c":false},{"l":"B","t":"Orthopédique","c":false},{"l":"C","t":"Chirurgical","c":true},{"l":"D","t":"Ambulatoire","c":false},{"l":"E","t":"Médical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1418, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'La complication urologique la plus fréquente après une fracture du bassin est :', '[{"l":"A","t":"Une atteinte du rein","c":false},{"l":"B","t":"Une rupture de l’uretère","c":false},{"l":"C","t":"Une rupture de la vessie","c":true},{"l":"D","t":"Une atteinte de l’urètre","c":false},{"l":"E","t":"Une infection urinaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1419, 8, 'Autre', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le traitement chirurgical est indiqué en cas de :', '[{"l":"A","t":"Échec du traitement médical","c":true},{"l":"B","t":"Douleur minime","c":false},{"l":"C","t":"Patient jeune","c":false},{"l":"D","t":"Patient âgé","c":false},{"l":"E","t":"Infection récente","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1420, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'méthode de réduction d’une fracture consiste à :', '[{"l":"A","t":"Immobiliser le foyer de fracture","c":false},{"l":"B","t":"Rétablir l’anatomie osseuse et l’axe fonctionnel","c":true},{"l":"C","t":"Nettoyer la plaie","c":false},{"l":"D","t":"Effectuer un drainage","c":false},{"l":"E","t":"Administrer un antibiotique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1421, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'La principale complication nerveuse d’une fracture de l’extrémité supérieure de l’humérus est l’atteinte :', '[{"l":"A","t":"Du nerf radial","c":false},{"l":"B","t":"Du nerf médian","c":false},{"l":"C","t":"Du nerf axillaire","c":true},{"l":"D","t":"Du nerf musculo-cutané","c":false},{"l":"E","t":"Du plexus brachial","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1422, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'La fracture du col chirurgical de l’humérus est une fracture :', '[{"l":"A","t":"Extra-articulaire","c":true},{"l":"B","t":"Intra-articulaire","c":false},{"l":"C","t":"Diaphysaire","c":false},{"l":"D","t":"Épiphyso-métaphysaire","c":false},{"l":"E","t":"De la tête humérale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1423, 43, 'Traumatologie', 'Syndrome des loges', NULL, false, true, 'Le “débridement chirurgical” est une intervention réalisée pour :', '[{"l":"A","t":"Réduire une luxation","c":false},{"l":"B","t":"Traiter un syndrome des loges","c":false},{"l":"C","t":"Nettoyer et exciser les tissus nécrosés dans une fracture ouverte","c":true},{"l":"D","t":"Réduire une fracture fermée ERéparer une lésion ligamentaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1424, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'La fracture de la tête radiale est souvent associée à :', '[{"l":"A","t":"Une luxation de l’épaule","c":false},{"l":"B","t":"Une luxation du coude","c":true},{"l":"C","t":"Une fracture du fémur","c":false},{"l":"D","t":"Une entorse du genou","c":false},{"l":"E","t":"Une fracture de la clavicule","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1425, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'principal risque après une fracture du bassin est :', '[{"l":"A","t":"Le syndrome des loges","c":false},{"l":"B","t":"La nécrose avasculaire de la tête fémorale","c":false},{"l":"C","t":"La pseudarthrose","c":false},{"l":"D","t":"Le choc hémorragique","c":true},{"l":"E","t":"L’infection","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1426, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Le cal vicieux est une complication :', '[{"l":"A","t":"Fréquente chez l’enfant","c":true},{"l":"B","t":"Rare chez l’enfant","c":false},{"l":"C","t":"Tardive","c":false},{"l":"D","t":"Immédiate","c":false},{"l":"E","t":"Systématique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1427, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Le principal signe clinique d’une fracture de la patella est :', '[{"l":"A","t":"L’impossibilité de la flexion","c":false},{"l":"B","t":"L’impossibilité de l’extension","c":true},{"l":"C","t":"Une douleur minime","c":false},{"l":"D","t":"Une déformation en valgus","c":false},{"l":"E","t":"Une déformation en varus","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1428, 8, 'Autre', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le traitement d’une fracture est fonction de plusieurs facteurs. Lequel de ces facteurs n’est pas pertinent pour le choix du traitement ?', '[{"l":"A","t":"Le type de fracture","c":false},{"l":"B","t":"L’âge du patient","c":false},{"l":"C","t":"Les comorbidités du patient","c":false},{"l":"D","t":"Le mois de l’année où a eu lieu la fracture","c":true},{"l":"E","t":"La localisation de la fracture","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1429, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le risque de pseudarthrose est élevé en cas de :', '[{"l":"A","t":"Fracture ouverte","c":true},{"l":"B","t":"Fracture fermée","c":false},{"l":"C","t":"Patient jeune","c":false},{"l":"D","t":"Traitement chirurgical","c":false},{"l":"E","t":"Immobilisation plâtrée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1430, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Parmi les signes cliniques suivants, lequel n’est pas un signe de fracture ?', '[{"l":"A","t":"Douleur","c":false},{"l":"B","t":"Impotence fonctionnelle absolue","c":false},{"l":"C","t":"Œdème","c":false},{"l":"D","t":"Hémarthrose","c":true},{"l":"E","t":"Crépitation osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1431, 8, 'Autre', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le diagnostic d’une fracture est confirmé par :', '[{"l":"A","t":"Le scanner","c":false},{"l":"B","t":"L''IRM","c":false},{"l":"C","t":"L''échographie","c":false},{"l":"D","t":"La radiographie standard","c":true},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1432, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'Une fracture de l’extrémité supérieure de l’humérus avec un important déplacement peut causer un risque de :', '[{"l":"A","t":"Lésion de la rate","c":false},{"l":"B","t":"Lésion du poumon","c":false},{"l":"C","t":"Lésion de la plèvre","c":true},{"l":"D","t":"Lésion du foie","c":false},{"l":"E","t":"Lésion du rein","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1433, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'L’ostéosynthèse est réalisée par :', '[{"l":"A","t":"Un clou","c":false},{"l":"B","t":"Des broches","c":false},{"l":"C","t":"Des vis et une plaque","c":true},{"l":"D","t":"Un fixateur externe","c":false},{"l":"E","t":"Une prothèse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1434, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'La pseudarthrose est une complication :', '[{"l":"A","t":"Immédiate des fractures","c":false},{"l":"B","t":"Précoce des fractures","c":false},{"l":"C","t":"Tardive des fractures","c":true},{"l":"D","t":"Liée à une luxation","c":false},{"l":"E","t":"Liée à une entorse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1435, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', NULL, false, true, 'Le diagnostic d’une fracture de la jambe est fait par :', '[{"l":"A","t":"L’échographie","c":false},{"l":"B","t":"L’IRM","c":false},{"l":"C","t":"La radiographie de la jambe, incluant genou et cheville","c":true},{"l":"D","t":"Le scanner","c":false},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1436, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'La consolidation osseuse chez l’enfant est favorisée par :', '[{"l":"A","t":"La faible vascularisation","c":false},{"l":"B","t":"La forte vascularisation","c":true},{"l":"C","t":"L’âge","c":false},{"l":"D","t":"Le poids","c":false},{"l":"E","t":"La taille","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1437, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', NULL, false, true, 'Le traitement d''une fracture ouverte de la jambe est :', '[{"l":"A","t":"L''immobilisation simple","c":false},{"l":"B","t":"La chirurgie, par un débridement chirurgical en urgence","c":true},{"l":"C","t":"Le plâtre","c":false},{"l":"D","t":"La traction continue","c":false},{"l":"E","t":"La pose d''une plaque et des vis","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1438, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Le traitement chirurgical d’une fracture de l’extrémité supérieure de l’humérus est indiqué en cas de :', '[{"l":"A","t":"Fracture déplacée et instable","c":true},{"l":"B","t":"Fracture non déplacée","c":false},{"l":"C","t":"Fracture chez un patient âgé","c":false},{"l":"D","t":"Fracture chez un enfant","c":false},{"l":"E","t":"Douleur minime","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1439, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'La consolidation d’une fracture supracondylienne chez l’enfant est généralement :', '[{"l":"A","t":"Très longue","c":false},{"l":"B","t":"Rapide","c":true},{"l":"C","t":"Difficile","c":false},{"l":"D","t":"Avec un risque élevé de pseudarthrose","c":false},{"l":"E","t":"Toujours associée à un cal vicieux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1440, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le traitement des fractures non déplacées est :', '[{"l":"A","t":"Toujours chirurgical","c":false},{"l":"B","t":"Fonctionnel, avec une attelle ou une écharpe","c":true},{"l":"C","t":"Une traction continue","c":false},{"l":"D","t":"Un plâtre","c":false},{"l":"E","t":"Une arthrodèse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1441, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'La radiographie standard pour le diagnostic doit inclure une incidence :', '[{"l":"A","t":"De profil","c":false},{"l":"B","t":"De trois-quarts","c":false},{"l":"C","t":"De face comparative","c":true},{"l":"D","t":"De l’épaule","c":false},{"l":"E","t":"Du coude","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1442, 25, 'Traumatologie', 'Fracture diaphysaire des deux os de l’avant-bras', NULL, false, true, 'Une fracture de la tête radiale est souvent associée à une lésion de :', '[{"l":"A","t":"L’artère radiale","c":false},{"l":"B","t":"L’artère brachiale","c":false},{"l":"C","t":"Le nerf radial","c":false},{"l":"D","t":"Le ligament latéral interne du coude","c":false},{"l":"E","t":"Le ligament latéral externe du coude","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1443, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Le diagnostic d’une fracture du bassin est fait par :', '[{"l":"A","t":"L’échographie","c":false},{"l":"B","t":"L’IRM","c":false},{"l":"C","t":"La radiographie du bassin","c":true},{"l":"D","t":"Le scanner","c":false},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
