(1495, 32, 'Rhumatologie', 'Fracture de l’humérus', NULL, false, true, '8 La classification de Neer est utilisée pour les fractures de l’extrémité supérieure de l’humérus. Elle est basée sur le nombre de fragments. Quel est le nombre de fragments ?', '[{"l":"A","t":"1 fragment","c":false},{"l":"B","t":"2 fragments","c":false},{"l":"C","t":"3 fragments","c":false},{"l":"D","t":"4 fragments","c":false},{"l":"E","t":"Tous les fragments","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1496, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, '9 La pseudarthrose est une complication :', '[{"l":"A","t":"Immédiate","c":false},{"l":"B","t":"Précoce","c":false},{"l":"C","t":"Tardive","c":true},{"l":"D","t":"Liée à une luxation","c":false},{"l":"E","t":"Liée à une entorse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1497, 25, 'Traumatologie', 'Fracture diaphysaire des deux os de l’avant-bras', NULL, false, true, '0 La complication la plus fréquente après une fracture de la tête radiale est :', '[{"l":"A","t":"Le syndrome des loges","c":false},{"l":"B","t":"La pseudarthrose","c":false},{"l":"C","t":"La raideur du coude","c":true},{"l":"D","t":"Le cal vicieux","c":false},{"l":"E","t":"La nécrose avasculaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1498, 5, 'Rhumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Une algodystrophie peut être précédée par : cochez la ou les réponse(s) juste(s) :', '[{"l":"A","t":"Une infection ostéoarticulaire","c":false},{"l":"B","t":"Une chirurgie orthopédique","c":true},{"l":"C","t":"Un phénomène de Raynaud","c":false},{"l":"D","t":"Un accident vasculaire cérébral","c":true},{"l":"E","t":"Une entorse","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1499, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Une algodystrophie peut se manifester par : cochez la ou les réponse(s) juste(s) :', '[{"l":"A","t":"Œdème","c":true},{"l":"B","t":"Troubles de la sudation","c":true},{"l":"C","t":"Déformations articulaires précoces irréversibles","c":false},{"l":"D","t":"Modification de la coloration cutanée","c":true},{"l":"E","t":"Troubles trophiques cutanés et unguéaux","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1500, 8, 'Autre', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le traitement médical consiste en :', '[{"l":"A","t":"Des antalgiques","c":false},{"l":"B","t":"Des anti-inflammatoires non stéroïdiens","c":false},{"l":"C","t":"Des corticoïdes","c":false},{"l":"D","t":"Des médicaments pour la douleur neuropathique","c":true},{"l":"E","t":"Des antibiotiques","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1501, 24, 'Autre', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Traumatisme du rachis : 1 Parmi les éléments suivants, quelles sont qui font partie du segment mobile rachidien :', '[{"l":"A","t":"Les pédicules","c":false},{"l":"B","t":"Le ligament jaune","c":true},{"l":"C","t":"Le mur postérieur du corps vertébral","c":false},{"l":"D","t":"Le disque","c":true},{"l":"E","t":"Le ligament vertébral commun postérieur","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1502, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Quelle est la conduite à tenir devant un premier épisode de lombosciatique commune ?', '[{"l":"A","t":"repos strict en décubitus ventral","c":false},{"l":"B","t":"antalgiques et anti-inflammatoires non stéroïdiens","c":true},{"l":"C","t":"infiltration épidurale par un dérivé cortisonique","c":false},{"l":"D","t":"un scanner du rachis lombaire si amélioration partielle au traitement médical","c":false},{"l":"E","t":"physiothérapie antalgique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1503, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Concernant la sciatique S1, laquelle de ces affirmations est correcte ?', '[{"l":"A","t":"La douleur irradie vers le gros orteil","c":false},{"l":"B","t":"Le réflexe achilléen est aboli","c":true},{"l":"C","t":"Le déficit moteur concerne l’extension du genou","c":false},{"l":"D","t":"Le test de Lasègue est positif en dedans","c":false},{"l":"E","t":"L’hypoesthésie siège sur le bord externe du pied","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1504, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Concernant la BURST fracture au rachis dorso-lombaire, laquelle de ces affirmations est correcte ?', '[{"l":"A","t":"Est un type A3 de MAGERL","c":true},{"l":"B","t":"Est due à un mécanisme en distraction","c":false},{"l":"C","t":"Est une lésion instable","c":true},{"l":"D","t":"Peut donner des lésions neurologiques par recul du mur postérieur","c":true},{"l":"E","t":"Nécessite toujours une laminectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1505, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Concernant la spondylolyse L5-S1, laquelle de ces affirmations est correcte ?', '[{"l":"A","t":"Est une solution de continuité de l’isthme vertébral","c":true},{"l":"B","t":"Est souvent asymptomatique","c":true},{"l":"C","t":"Peut évoluer vers une spondylolisthésis","c":true},{"l":"D","t":"Se voit essentiellement sur le rachis dorsal","c":false},{"l":"E","t":"Le scanner est l’examen de référence","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1506, 26, 'Traumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'Les complications immédiates à rechercher devant un traumatisme du bassin :', '[{"l":"A","t":"Atteinte de l’urètre","c":true},{"l":"B","t":"Atteinte du plexus sacré","c":false},{"l":"C","t":"Atteinte de la vessie","c":true},{"l":"D","t":"Atteinte vasculaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1507, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Les signes inhabituels d’une sciatique de topographie S1 sont :', '[{"l":"A","t":"Aréflexie rotulienne","c":true},{"l":"B","t":"Aréflexie achiliéenne","c":false},{"l":"C","t":"Difficulté de se tenir sur les talons","c":false},{"l":"D","t":"Hypotonie du mollet","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1508, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'La scoliose idopathique de l’enfant :', '[{"l":"A","t":"est la plus fréquente des scolioses de l’enfant","c":true},{"l":"B","t":"prédominante chez les garçons","c":false},{"l":"C","t":"se caractérise par une douleure a la percusion","c":false},{"l":"D","t":"comporte une gibbsite lorsque l’enfant penche en avant","c":true},{"l":"E","t":"grave par ses conséquences morphologiques et fonctionnelles son traitement est long, lourd et couteux.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1509, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'la scoliose est caractérisé par : cocher la réponse fausse', '[{"l":"A","t":"est une déformation rachidienne apparaissant et évoluant pendant la période de croissance.","c":false},{"l":"B","t":"sur le plan frontale en inclinaison latérale, incurvation à convexité dorsale ou lombaire.","c":false},{"l":"C","t":"sur le plan sagittale en extension, perte ou accentuation de la cyphose dorsale ou de la lordose lombaire.","c":false},{"l":"D","t":"sur le plan horizontale en rotation axiale, rotation des corps vertébraux traduite par une gibbosité.","c":false},{"l":"E","t":"Cette déformation rachidienne a une relation avec un processus pathologique décelable.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1510, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Les signes évocateurs d’une sciatique de topographie LS sont :', '[{"l":"A","t":"Douleur à la face postéro-externe de la cuisse, postérieure de la jambe","c":true},{"l":"B","t":"Hypoesthésie du dos du pied","c":true},{"l":"C","t":"Abolition du reflexe rotulien","c":false},{"l":"D","t":"Marche sur les talons impossible","c":false},{"l":"E","t":"Diminution de la force de l’extenseur propre du gros orteil","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1511, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Devant une lombosciatique LS d’origine discale, la sanction chirurgicale formelle se pose devant :', '[{"l":"A","t":"La survenue d’un épisode hyperalgique","c":false},{"l":"B","t":"Signe de Lasègue positif à 50°","c":false},{"l":"C","t":"Apparition d’un Steppage","c":true},{"l":"D","t":"Abolition du reflexe achilléen","c":false},{"l":"E","t":"Prortusion discale au scanner","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1512, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'au niveau du rachis :(cochez la réponse juste)', '[{"l":"A","t":"la moelle est plus longue que le canal rachidien d’où décalage entre le niveau vertébral et celui du méthanère médullaire","c":false},{"l":"B","t":"La moelle épinière chemine dans un canal ostéo-ligamentaire inextensible","c":true},{"l":"C","t":"elle contient des motoneurones motrices seulement","c":false},{"l":"D","t":"les cornes antérieures sont responsables de la sensibilité","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1513, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'La suspicion d’une fracture du rachis cervical chez un polytraumatisé : (cochez la/les réponses justes)', '[{"l":"A","t":"Ne nécessite pas la pose de minerve pour le transport.","c":false},{"l":"B","t":"Interdit la réalisation d’une intubation.","c":false},{"l":"C","t":"Ne nécessite pas une désincarcération en traction.","c":false},{"l":"D","t":"Contre-indique de faire un massage cardiaque.","c":false},{"l":"E","t":"Un examen neurologique des membres supérieurs est indiqué sur les lieux même de l’accident.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1514, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'La différence entre scoliose et attitude scoliotique réside dans : (cochez la ou les réponses justes) :', '[{"l":"A","t":"La gibbosité qui est absente dans la scoliose et présente dans l’attitude scoliotique","c":false},{"l":"B","t":"La gibbosité qui est présente dans la scoliose et absente dans l’attitude scoliotique","c":true},{"l":"C","t":"L’angle de COBB qui dépasse 50 °en cas de scoliose","c":false},{"l":"D","t":"La présence de rotation vertébrale à la radiographie dans la scoliose","c":true},{"l":"E","t":"L’absence de rotation vertébrale dans l’attitude scoliotique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1515, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Dans la lombosciatique (commune) (la réponse fausse) :', '[{"l":"A","t":"La hernie discale et l’arthrose zygapophysaire sont les causes les plus fréquentes","c":false},{"l":"B","t":"Une radio standard de rachis lombaire est indispensable au diagnostic, elle est demandée dès la première semaine d’évolution.","c":true},{"l":"C","t":"Le trajet de la douleur, son rythme mécanique et les antécédents de douleurs lombaires aiguës permettent, dans la plupart des cas, de poser le diagnostic","c":false},{"l":"D","t":"Un déficit moteur côté à 3 ou moins est un signe de gravité et impose la réalisation d’une IRM du rachis lombaire afin de discuter un traitement chirurgical","c":false},{"l":"E","t":"La tendinopathie du moyen fessier est un diagnostic différentiel","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1516, 23, 'Rhumatologie', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'Une attitude scoliotique est caractérisée par (réponse juste):', '[{"l":"A","t":"Un angle de Cobb supérieur à 10°","c":false},{"l":"B","t":"Une gibbosité thoracique","c":false},{"l":"C","t":"Une rotation de la vertèbre sommet","c":false},{"l":"D","t":"Sa réductibilité à l’examen du tronc penché en avant","c":true},{"l":"E","t":"Une déformation de la colonne vertébrale dans les trois plans de l’espace","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1517, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Devant une lombosciatique :', '[{"l":"A","t":"Une fièvre, un amaigrissement, avec une recrudescence douloureuse nocturne imposent la recherche d’une cause infectieuse ou tumorale.","c":true},{"l":"B","t":"Une abolition du réflexe tendineux calcanéen, est évocateur d’une atteinte L5","c":false},{"l":"C","t":"Les antalgiques, les AINS, associés à des décontracturants musculaires, constituent le traitement de première intention dans la sciatique commune non compliquée.","c":true},{"l":"D","t":"Le maintien d’une activité adaptée à l’importance de la douleur est conseillé.","c":true},{"l":"E","t":"Le repos strict sur un plan dur est conseillé.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1518, 34, 'Autre', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Au cours d’une radiculalgie S1: Cochez-la ou les réponses fausses', '[{"l":"A","t":"Aréflexie Achiléenne","c":false},{"l":"B","t":"Dysesthésie à la face externe de la cuisse","c":true},{"l":"C","t":"Déficit du jambier postérieur","c":false},{"l":"D","t":"Hypoesthésie du dos de pied","c":false},{"l":"E","t":"Déficit du psoas","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1519, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Concernant la lombosciatique commune : Cochez-la ou les réponse(s) fausses', '[{"l":"A","t":"Considérée comme une urgence neurochirurgicale d’emblée","c":true},{"l":"B","t":"Résulte souvent d’une anomalie discale","c":false},{"l":"C","t":"Paralysante en cas d’un déficit moteur complet","c":false},{"l":"D","t":"Signe de LERI positif","c":true},{"l":"E","t":"Bilan inflammatoire perturbé","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1520, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Concernant la Lombosciatique commune :', '[{"l":"A","t":"considérée comme une urgence neurochirurgicale d’emblée","c":false},{"l":"B","t":"résulte souvent d’une anomalie discale","c":true},{"l":"C","t":"paralysante en cas d’un déficit moteur complet","c":true},{"l":"D","t":"signe de LERI positif","c":false},{"l":"E","t":"bilan inflammatoire perturbé","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1521, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'Le diagnostic radiologique de la scoliose idiopathique chez l’enfant se fait devant :', '[{"l":"A","t":"la présence d’une rotation de vertèbres","c":true},{"l":"B","t":"une déviation frontale des vertèbres par rapport à la ligne médiane","c":true},{"l":"C","t":"un angle de Cobb supérieur à 10°","c":true},{"l":"D","t":"une déformation congénitale des vertèbres (hémi vertèbres)","c":false},{"l":"E","t":"un Risser 4","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1522, 34, 'Autre', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Au cours d’une radiculalgie S1, on retrouve classiquement :', '[{"l":"A","t":"aréflexie Achilléenne","c":true},{"l":"B","t":"dysesthésie de la face externe de la cuisse","c":false},{"l":"C","t":"déficit du jambier postérieur","c":false},{"l":"D","t":"hypoesthésie du dos du pied","c":true},{"l":"E","t":"déficit du psoas","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1523, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Une fracture du rachis peut être associée à :', '[{"l":"A","t":"Une fracture de la clavicule","c":false},{"l":"B","t":"Une fracture du bassin","c":true},{"l":"C","t":"Une fracture du fémur","c":false},{"l":"D","t":"Une fracture de la patella","c":false},{"l":"E","t":"Une fracture du tibia","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1524, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Le “syndrome de la queue de cheval” est une complication d’une fracture de :', '[{"l":"A","t":"L’humérus","c":false},{"l":"B","t":"Le fémur","c":false},{"l":"C","t":"Le rachis lombaire bas","c":true},{"l":"D","t":"Le rachis thoracique","c":false},{"l":"E","t":"Le rachis cervical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
