(1527, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'La douleur de la sciatique est souvent :', '[{"l":"A","t":"L’après-midi","c":false},{"l":"B","t":"Le matin","c":false},{"l":"C","t":"La nuit","c":true},{"l":"D","t":"Le soir","c":false},{"l":"E","t":"La journée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
