(1560, 24, 'Autre', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Traumatisme Du Rachis 66 L’entorse grave du rachis cervical (réponse fausse) :', '[{"l":"A","t":"Entraîne un antélisthésis","c":false},{"l":"B","t":"Peut-être diagnostiquée par des clichés dynamiques","c":false},{"l":"C","t":"Peut donner une radio normale","c":false},{"l":"D","t":"La lésion ligamentaire provoquée est irréversible","c":true},{"l":"E","t":"Peut être traitée orthopédiquement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1561, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Le traumatisme vertébro-médullaire est caractérisé par (la réponse fausse):', '[{"l":"A","t":"Une phase flasque (choc spinal)","c":false},{"l":"B","t":"Une phase spastique du retour de l’automatisme médullaire au niveau de la partie sous-jacente à la lésion","c":false},{"l":"C","t":"Une para ou une tétraplégie","c":false},{"l":"D","t":"Des troubles vésicosphinctériens","c":false},{"l":"E","t":"Des lésions toujours complètes de la moelle épinière","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1562, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'La BURST fracture au rachis dorso-lombaire : (cocher la ou les réponses justes)', '[{"l":"A","t":"Est un type A2 de MAGERL","c":false},{"l":"B","t":"Entraîne une instabilité mixte","c":false},{"l":"C","t":"Peut donner des lésions neurologiques par recul du mur postérieur","c":true},{"l":"D","t":"Est due à un mécanisme en compression","c":true},{"l":"E","t":"Nécessite toujours une laminectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
