(1564, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Le patient avec un traumatisme du rachis présente un signe d’alerte. Lequel ?', '[{"l":"A","t":"Une douleur au niveau du dos","c":true},{"l":"B","t":"Une douleur au niveau du cou","c":false},{"l":"C","t":"Une douleur au niveau des membres","c":false},{"l":"D","t":"Une douleur au niveau du bassin","c":false},{"l":"E","t":"Une douleur au niveau de la tête","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1565, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Principes de base en médecine physique et de réadaptation [ + complication de l’immobilite et du decubitus ] 1 La médecine Physique et de Réadaptation : cochez la ou les réponse(s) juste(s)', '[{"l":"A","t":"Est une spécialité médicale visant l’amélioration du fonctionnement physique et cognitif","c":true},{"l":"B","t":"Son but est de traiter l’organe","c":false},{"l":"C","t":"Elle est définie par un objectif qui est la fonction","c":true},{"l":"D","t":"Il s’agit d’une spécialité qui n’est pas déterminée par une population spécifique ou un organe spécifique","c":true},{"l":"E","t":"C’est une spécialité qui prend en charge uniquement des adultes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1566, 12, 'MPR', 'Membre inférieur et locomotion', NULL, false, true, 'Dans la marche (cochez la ou les réponses justes) :', '[{"l":"A","t":"La phase oscillante représente environ 60 % du cycle de la marche","c":false},{"l":"B","t":"Le double appui n’existe pas dans la marche normale","c":false},{"l":"C","t":"La phase d’appui représente environ 60% du cycle de la marche","c":true},{"l":"D","t":"La réception par le talon marque le début de la phase oscillante","c":false},{"l":"E","t":"Le décollage des orteils, marque la fin de la phase d’appui et le début de la phase oscillante","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1567, 1, 'Autre', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Les troubles orthopédiques post poliomyélite sont caractérisé par :', '[{"l":"A","t":"paralysie suivie d’une amyotrophie musculaire","c":true},{"l":"B","t":"douleurs suite a une rétraction musculaire","c":true},{"l":"C","t":"modification de croissance dans les segments paralysies","c":true},{"l":"D","t":"potentiel d’aggravation par la croissance","c":true},{"l":"E","t":"retentissement fonctionnelle par la perte de force certain muscle","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1568, 10, 'Autre', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Un syndrome ostéomalacique peut être responsable d’une : (cochez les propositions correctes)', '[{"l":"A","t":"Hypocalcémie","c":true},{"l":"B","t":"Hypophosphatémie","c":true},{"l":"C","t":"Hypophosphatasie","c":false},{"l":"D","t":"Hypovitaminose D","c":true},{"l":"E","t":"Hyperparathyroïdie primitive","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1569, 13, 'MPR', 'Membre supérieur et préhension', NULL, false, true, 'Concernant la préhension : Quelle(s) est (sont) la (les) proposition(s) exacte(s) ?', '[{"l":"A","t":"Le nerf musculocutané assure l’innervation sensitive de la paume de la main.","c":false},{"l":"B","t":"Pour pouvoir saisir un objet, l’orientation de la main est réalisée uniquement au niveau du poignet.","c":false},{"l":"C","t":"Chez le patient hémiplégique vasculaire les structures corticales sont responsables de symptômes affectant la capacité de préhension.","c":true},{"l":"D","t":"Chez le tétraplégique, l’ouverture de la main est assurée par la mise en extension du poignet.","c":false},{"l":"E","t":"Dans la main rhumatoïde, l’Orthèse « anti-coup de vent ulnaire » permet de stabiliser les articulations métacarpophalangiennes.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1570, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'La prévention des escarres comporte : (cochez la réponse juste)', '[{"l":"A","t":"Matelas anti escarre.","c":false},{"l":"B","t":"Changement de position toutes les 2 à 4 heures.","c":false},{"l":"C","t":"Surveiller systématiquement tous les points d’appui.","c":false},{"l":"D","t":"Prévenir toute macération.","c":false},{"l":"E","t":"Toutes les réponses sont justes.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1571, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Les objectifs de rééducation en Traumatologie-Orthopédie en phase aiguë sont : (cochez les réponses justes)', '[{"l":"A","t":"Prévenir les complications liées au décubitus et à la douleur.","c":true},{"l":"B","t":"Favoriser l’indépendance fonctionnelle du patient.","c":true},{"l":"C","t":"Prévenir les attitudes vicieuses, l’enraidissement articulaire et la fonte musculaire.","c":true},{"l":"D","t":"Récupérer des amplitudes articulaires et une force musculaire maximale.","c":false},{"l":"E","t":"Toutes les réponses sont justes.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1572, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Concernant les techniques et les moyens utilisés en rééducation rhumatologique : Quelle(s) est (sont) la (les) proposition(s) juste(s) ?', '[{"l":"A","t":"Le renforcement musculaire contre résistance est utilisé pendant les poussées inflammatoires.","c":false},{"l":"B","t":"La physiothérapie est utilisée sous forme de chaud en période inflammatoire.","c":false},{"l":"C","t":"La mobilisation passive forcée et les postures sont indiquées en phase de poussée inflammatoire.","c":false},{"l":"D","t":"L’orthèse est un dispositif médical externe pharmacologique appliqué à un membre ou rachis.","c":false},{"l":"E","t":"Les Orthèses de repos sont utilisées à visée antalgique et préventive des déformations.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1573, 12, 'MPR', 'Membre inférieur et locomotion', NULL, false, true, 'Les troubles de la marche peuvent être d’origine : (cochez la réponse juste)', '[{"l":"A","t":"Traumatique.","c":false},{"l":"B","t":"Neurologique.","c":false},{"l":"C","t":"Douloureuse.","c":false},{"l":"D","t":"Psychogène.","c":false},{"l":"E","t":"Toutes les réponses sont justes.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1574, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Complications cutanées : escarres (cochez la/les réponses justes)', '[{"l":"A","t":"L’escarre est une lésion d’origine ischémique des tissus cutané et sous-cutané.","c":true},{"l":"B","t":"L’escarre est liée à une pression prolongée des parties molles, en regard d’un relief osseux.","c":true},{"l":"C","t":"Elle peut apparaître lors d’un appui prolongé au-delà de 10 heures.","c":false},{"l":"D","t":"Toutes les réponses sont justes.","c":false},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1575, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Les moyens préventifs des complications thromboemboliques. sont (les réponses justes):', '[{"l":"A","t":"La verticalisation précoce","c":true},{"l":"B","t":"La contention veineuse élastique","c":true},{"l":"C","t":"Les massages de drainage","c":false},{"l":"D","t":"La mobilisation articulaire et le renforcement musculaire","c":true},{"l":"E","t":"Les anti-inflammatoires non stéroïdiens","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1576, 11, 'Autre', 'Boiterie chez l’enfant', NULL, false, true, 'En cas de hanche douloureuse, il y a des signes d’alerte à rechercher (cochez la ou les réponses justes) :', '[{"l":"A","t":"Un contexte fébrile","c":true},{"l":"B","t":"Une altération de l’état général","c":true},{"l":"C","t":"Une douleur chronique","c":false},{"l":"D","t":"La constatation d’un gonflement articulaire ou d’une voussure localisée","c":true},{"l":"E","t":"Limitation de l’amplitude articulaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1577, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Dans les complications du décubitus les escarres (les réponses fausses):', '[{"l":"A","t":"Représentent une des complications les plus précoces","c":false},{"l":"B","t":"Elles résultent des phénomènes intrinsèques et extrinsèques","c":false},{"l":"C","t":"Le stade 3 : est un érythème persistant qui ne disparaît pas à la pression","c":true},{"l":"D","t":"Peut se compliquer d’une infection","c":false},{"l":"E","t":"Leur siège électif en décubitus dorsal est le trochanter","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1578, 3, 'Autre', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'L’axonotmésis dans la classification de Seddon des lésions nerveuses périphériques (cocher la ou les réponses justes) :', '[{"l":"A","t":"Est une interruption fonctionnelle de la conduction nerveuse sans lésion axonale.","c":false},{"l":"B","t":"Toutes les structures nerveuses sont sectionnées,","c":false},{"l":"C","t":"Est une lésion neurologique grave sans récupération.","c":false},{"l":"D","t":"Correspond aux stades: 2, 3 et 4 de Sunderland,","c":true},{"l":"E","t":"Les structures conjonctives sont en grande partie intactes et guideront la réinnervation","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1579, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Le ou les signes du syndrome douloureux régional complexe de type I au niveau des mains : (cocher la ou les réponses justes)', '[{"l":"A","t":"Douleur.","c":true},{"l":"B","t":"Œdème.","c":true},{"l":"C","t":"Hypoesthésie dans le territoire du nerf médian.","c":false},{"l":"D","t":"Abolition des pouls.","c":false},{"l":"E","t":"Hypersudation.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1580, 29, 'MPR', 'Algoneurodystrophie', NULL, false, true, 'L’immobilisation entraîne : (cocher la ou les réponses justes)', '[{"l":"A","t":"Une déminéralisation osseuse.","c":true},{"l":"B","t":"Un enraidissement articulaire.","c":true},{"l":"C","t":"Des para-ostéo-arthropathies neurogènes (PAON).","c":false},{"l":"D","t":"Une algoneurodystrophie","c":false},{"l":"E","t":"Une amyotrophie.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1581, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Les escarres : (cochez la ou les réponses fausses)', '[{"l":"A","t":"Sont provoquées par une compression des parties molles sur les reliefs osseux.","c":false},{"l":"B","t":"Doivent être prévenues par les retournements, l’utilisation d’un support adapté et la prévention de la macération","c":false},{"l":"C","t":"Selon la profondeur des lésions, on distingue deux stades : stade 1: érythème; stade 2: perte de substance profonde, touchant les trois couches de la peau","c":true},{"l":"D","t":"Leur localisation correspond aux zones d’appui selon la position du patient","c":false},{"l":"E","t":"Quel que soit leur stade, les lésions sont réversibles avec la prévention et les soins locaux.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1582, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'Le principal risque d’une paraplégie ou d’une tétraplégie est :', '[{"l":"A","t":"L’infection","c":false},{"l":"B","t":"La pseudarthrose","c":false},{"l":"C","t":"Le cal vicieux","c":false},{"l":"D","t":"Les complications de décubitus","c":true},{"l":"E","t":"L’atteinte nerveuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
